// first index where condition(mid) is true (condition goes false...false, true...true)
int lo = 0, hi = n;                 // hi = n means "not found"
while (lo < hi) {
    int mid = lo + (hi - lo) / 2;   // avoids int overflow
    if (condition(mid)) hi = mid;
    else lo = mid + 1;
}
return lo;

