void backtrack(List<Integer> path, boolean[] used, int[] nums, List<List<Integer>> out) {
    if (path.size() == nums.length) {          // complete?
        out.add(new ArrayList<Integer>(path)); // copy!
        return;
    }
    for (int i = 0; i < nums.length; i++) {    // choices
        if (used[i]) continue;
        used[i] = true; path.add(nums[i]);     // choose
        backtrack(path, used, nums, out);      // explore
        path.remove(path.size() - 1); used[i] = false;   // un-choose
    }
}

